  bottom: 0;
  left: 0;
  right: 0;
  height: 40px;
  display: flex;
  align-items: stretch;
  z-index: 9999;
  background: rgba(30, 30, 30, 0.85);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-top: 1px solid rgba(255,255,255,0.1);
}

#taskbar-left {
  flex: 1;
  display: flex;
  align-items: center;
  padding: 4px 8px;
  gap: 2px;
  min-width: 0;
}

#taskbar-clock {
  display: flex;
  align-items: center;
  padding: 0 16px;
  font-size: 12px;
  color: rgba(255,255,255,0.9);
  white-space: nowrap;
  min-width: 80px;
  justify-content: center;
}

/* ---------- Taskbar Buttons ---------- */
.taskbar-button {
  display: flex;
  align-items: center;
  height: 32px;
  padding: 0 10px;
  border: none;
  border-radius: 6px;
  background: transparent;
  color: rgba(255,255,255,0.85);
  font-size: 12px;
  cursor: pointer;
  transition: background-color 0.15s ease;
  white-space: nowrap;
  max-width: 140px;
  overflow: hidden;
  text-overflow: ellipsis;
}

.taskbar-button:hover {
  background: rgba(255,255,255,0.12);
}

.taskbar-button:active {
  background: rgba(255,255,255,0.08);
}

.taskbar-button.active {
  background: rgba(255,255,255,0.18);
  color: #fff;
  box-shadow: 0 0 0 1px rgba(255,255,255,0.1) inset;
}

.taskbar-button.active::after {
  content: "";
  position: absolute;
  bottom: 1px;
  left: 50%;
  transform: translateX(-50%);
  width: 16px;
  height: 2px;
  border-radius: 1px;
  background: #4a90d9;
}

.taskbar-button {
  position: relative;
}

/* ---------- Windows ---------- */
.window {
  position: absolute;
  min-width: 200px;
  min-height: 150px;
  border-radius: 10px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  box-shadow: 0 8px 32px rgba(0,0,0,0.3), 0 2px 8px rgba(0,0,0,0.15);
  border: 1px solid rgba(255,255,255,0.1);
  background: #f5f5f5;
}

.window.focused {
  box-shadow: 0 12px 40px rgba(0,0,0,0.35), 0 3px 10px rgba(0,0,0,0.2);
  border-color: rgba(255,255,255,0.15);
}

.window.minimized {
  display: none;
}

/* ---------- Titlebar ---------- */
.window-titlebar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 8px;
