  user-select: none;
  -webkit-user-select: none;
}

/* ---------- Desktop ---------- */
#desktop {
  position: fixed;
  inset: 0;
  bottom: 40px; /* room for taskbar */
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
  overflow: hidden;
  z-index: 0;
}

/* ---------- Desktop Icons ---------- */
#desktop-icons {
  display: flex;
  flex-direction: column;
  flex-wrap: wrap;
  align-content: flex-start;
  gap: 8px;
  padding: 24px 32px;
  height: 100%;
  width: 100%;
  max-width: 120px;
}

.desktop-icon {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
