  background: transparent;
  color: #666;
  font-size: 16px;
  cursor: pointer;
  transition: background-color 0.15s ease, color 0.15s ease;
  flex-shrink: 0;
}

.window-close:hover {
  background: #e01a1a;
  color: #fff;
}

/* ---------- Window Content ---------- */
.window-content {
  flex: 1;
  padding: 0;
  overflow: auto;
  background: #fff;
}

/* Placeholder content for apps not yet implemented */
.window-content.placeholder {
  display: flex;
  align-items: center;
  justify-content: center;
  color: #999;
  font-size: 14px;
}

/* ---------- Resizer handle (bottom-right corner) ---------- */
.window .window-resizer {
  position: absolute;
  bottom: 0;
  right: 0;
  width: 16px;
  height: 16px;
